import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppTab {
  HABITS = 'habits',
  CLINICAL = 'clinical',
  RESEARCH = 'research',
}

export enum HabitCategory {
  LIFE = '生活',
  FITNESS = '健身',
  RESEARCH = '科研',
  FINANCE = '财商',
  PATIENT = '患者管理',
}

export interface Habit {
  id: string;
  name: string;
  category: HabitCategory;
  completedDates: string[]; // ISO Strings
}

export interface ClinicalAnalysis {
  diagnosis: string[];
  omitted: string[];
  medications: string[];
  guidelines: { title: string; url: string }[];
  scales: { name: string; items: string[] }[];
  plan: string;
  followUpTasks: string[];
}

export interface ResearchInsight {
  literatures: { title: string; journal: string; link: string }[];
  ideas: string[];
  managementTips: string[];
}

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeCase = async (description: string, imageBase64?: string) => {
  const ai = getAI();
  const prompt = `你是一个资深的临床医学专家。请根据以下病例描述（可能包含文字或图片内容），输出结构化的临床分析。
  内容要求：
  1. 可能的诊断（按概率排序）。
  2. 可能忽略的鉴别诊断或检查。
  3. 建议用药。
  4. 相关临床指南链接。
  5. 适合该病人的病情评估量表。
  6. 完整的诊疗方案模型。
  7. 基于诊疗方案生成的后续复查、换药打卡计划。

  病例描述: ${description}`;

  const contents: any = { parts: [{ text: prompt }] };
  if (imageBase64) {
    contents.parts.unshift({
      inlineData: {
        mimeType: 'image/jpeg',
        data: imageBase64,
      }
    });
  }

  const response = await ai.models.generateContent({
    model: imageBase64 ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
    contents,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          diagnosis: { type: Type.ARRAY, items: { type: Type.STRING } },
          omitted: { type: Type.ARRAY, items: { type: Type.STRING } },
          medications: { type: Type.ARRAY, items: { type: Type.STRING } },
          guidelines: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                url: { type: Type.STRING }
              }
            }
          },
          scales: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                items: { type: Type.ARRAY, items: { type: Type.STRING } }
              }
            }
          },
          plan: { type: Type.STRING },
          followUpTasks: { type: Type.ARRAY, items: { type: Type.STRING } }
        }
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const getResearchHelp = async (topic: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `针对研究方向 "${topic}"，请提供：1. 最新的高质量参考文献推荐（含标题、期刊和搜索链接）；2. 创新的科研点子；3. 科研管理与进度控制的建议。请确保信息真实可靠，使用Google搜索辅助。`,
    config: {
      tools: [{ googleSearch: {} }],
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          literatures: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                journal: { type: Type.STRING },
                link: { type: Type.STRING }
              }
            }
          },
          ideas: { type: Type.ARRAY, items: { type: Type.STRING } },
          managementTips: { type: Type.ARRAY, items: { type: Type.STRING } }
        }
      }
    }
  });
  return JSON.parse(response.text || '{}');
};

import React, { useState, useEffect } from 'react';
import { Habit, HabitCategory } from '../types';

export const HabitTracker: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('med-habits');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: '晨起喝水', category: HabitCategory.LIFE, completedDates: [] },
      { id: '2', name: '深蹲50个', category: HabitCategory.FITNESS, completedDates: [] },
      { id: '3', name: '阅读一篇文献', category: HabitCategory.RESEARCH, completedDates: [] },
      { id: '4', name: '记录当日开支', category: HabitCategory.FINANCE, completedDates: [] },
      { id: '5', name: '完成患者交班', category: HabitCategory.PATIENT, completedDates: [] },
    ];
  });

  const [newHabitName, setNewHabitName] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<HabitCategory>(HabitCategory.LIFE);

  useEffect(() => {
    localStorage.setItem('med-habits', JSON.stringify(habits));
  }, [habits]);

  const addHabit = () => {
    if (!newHabitName.trim()) return;
    const newHabit: Habit = {
      id: Date.now().toString(),
      name: newHabitName,
      category: selectedCategory,
      completedDates: []
    };
    setHabits([...habits, newHabit]);
    setNewHabitName('');
  };

  const deleteHabit = (id: string) => {
    setHabits(habits.filter(h => h.id !== id));
  };

  const toggleHabit = (id: string) => {
    const today = new Date().toISOString().split('T')[0];
    setHabits(habits.map(h => {
      if (h.id === id) {
        const isDone = h.completedDates.includes(today);
        return {
          ...h,
          completedDates: isDone 
            ? h.completedDates.filter(d => d !== today) 
            : [...h.completedDates, today]
        };
      }
      return h;
    }));
  };

  return (
    <div className="max-w-4xl mx-auto p-4 animate-fadeIn">
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 mb-6">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
          <i className="fa-solid fa-calendar-check text-indigo-500"></i>
          每日习惯养成
        </h2>
        <div className="flex flex-wrap gap-2 mb-4">
          <input 
            type="text" 
            value={newHabitName}
            onChange={(e) => setNewHabitName(e.target.value)}
            placeholder="输入新习惯..."
            className="flex-1 min-w-[200px] bg-slate-50 border border-slate-200 rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
          />
          <select 
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value as HabitCategory)}
            className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm"
          >
            {Object.values(HabitCategory).map(cat => (
              <option key={cat} value={cat}>{cat}</option>
            ))}
          </select>
          <button 
            onClick={addHabit}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-2 rounded-lg font-medium transition-colors"
          >
            添加
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {Object.values(HabitCategory).map(category => (
          <div key={category} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
            <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 font-semibold text-slate-600 text-sm">
              {category}
            </div>
            <div className="p-2 space-y-1">
              {habits.filter(h => h.category === category).map(habit => {
                const isDone = habit.completedDates.includes(new Date().toISOString().split('T')[0]);
                return (
                  <div key={habit.id} className="flex items-center justify-between p-3 hover:bg-slate-50 rounded-lg transition-colors group">
                    <div className="flex items-center gap-3">
                      <button 
                        onClick={() => toggleHabit(habit.id)}
                        className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${isDone ? 'bg-green-500 border-green-500 text-white' : 'border-slate-300 bg-white'}`}
                      >
                        {isDone && <i className="fa-solid fa-check text-[10px]"></i>}
                      </button>
                      <span className={`text-sm ${isDone ? 'line-through text-slate-400' : 'text-slate-700'}`}>
                        {habit.name}
                      </span>
                    </div>
                    <button 
                      onClick={() => deleteHabit(habit.id)}
                      className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all p-1"
                    >
                      <i className="fa-solid fa-trash-can text-xs"></i>
                    </button>
                  </div>
                );
              })}
              {habits.filter(h => h.category === category).length === 0 && (
                <p className="text-xs text-slate-400 p-4 text-center">暂无此类习惯</p>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { analyzeCase } from '../services/geminiService';
import { ClinicalAnalysis } from '../types';

export const ClinicalSystem: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [description, setDescription] = useState('');
  const [image, setImage] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<ClinicalAnalysis | null>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description && !image) return;
    setLoading(true);
    try {
      const result = await analyzeCase(description, image?.split(',')[1]);
      setAnalysis(result);
    } catch (error) {
      console.error(error);
      alert("分析失败，请稍后重试。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
          <i className="fa-solid fa-user-doctor text-blue-500"></i>
          规培带教与临床决策
        </h2>
        <div className="space-y-4">
          <textarea
            className="w-full h-32 bg-slate-50 border border-slate-200 rounded-xl p-4 focus:ring-2 focus:ring-blue-500 focus:outline-none transition-all"
            placeholder="描述病人主诉、病史、体征或化验结果..."
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <div className="flex items-center gap-4">
            <label className="flex items-center gap-2 cursor-pointer bg-slate-100 hover:bg-slate-200 px-4 py-2 rounded-lg text-sm text-slate-600 transition-colors">
              <i className="fa-solid fa-camera"></i>
              上传病例/化验单
              <input type="file" accept="image/*" onChange={handleImageUpload} className="hidden" />
            </label>
            {image && (
              <div className="relative group">
                <img src={image} className="h-10 w-10 object-cover rounded border border-slate-200" alt="Preview" />
                <button onClick={() => setImage(null)} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-4 h-4 flex items-center justify-center text-[8px] group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-xmark"></i>
                </button>
              </div>
            )}
            <button 
              onClick={handleAnalyze}
              disabled={loading}
              className="ml-auto bg-blue-600 hover:bg-blue-700 text-white px-8 py-2 rounded-lg font-bold disabled:bg-slate-400 flex items-center gap-2 transition-all shadow-lg shadow-blue-200"
            >
              {loading ? (
                <><i className="fa-solid fa-circle-notch animate-spin"></i> AI分析中...</>
              ) : (
                <><i className="fa-solid fa-wand-magic-sparkles"></i> 生成诊疗建议</>
              )}
            </button>
          </div>
        </div>
      </div>

      {analysis && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fadeIn">
          {/* Main Plan */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="text-lg font-bold text-slate-800 mb-3 border-l-4 border-blue-500 pl-3">诊断与用药建议</h3>
              <div className="space-y-4">
                <div>
                  <h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-2">可能的诊断</h4>
                  <div className="flex flex-wrap gap-2">
                    {analysis.diagnosis.map((d, i) => (
                      <span key={i} className="bg-blue-50 text-blue-700 px-3 py-1 rounded-full text-sm font-medium">{d}</span>
                    ))}
                  </div>
                </div>
                <div>
                  <h4 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-2">建议用药</h4>
                  <ul className="list-disc list-inside text-slate-700 space-y-1">
                    {analysis.medications.map((m, i) => <li key={i}>{m}</li>)}
                  </ul>
                </div>
                <div className="p-4 bg-amber-50 rounded-lg border border-amber-100">
                  <h4 className="text-sm font-semibold text-amber-700 mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-triangle-exclamation"></i> 易忽略的要点
                  </h4>
                  <ul className="list-disc list-inside text-amber-800 space-y-1 text-sm">
                    {analysis.omitted.map((o, i) => <li key={i}>{o}</li>)}
                  </ul>
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="text-lg font-bold text-slate-800 mb-3 border-l-4 border-emerald-500 pl-3">诊疗方案模型</h3>
              <div className="prose prose-slate max-w-none text-slate-700 whitespace-pre-wrap text-sm leading-relaxed">
                {analysis.plan}
              </div>
            </div>
          </div>

          {/* Sidebar: Guides and Tasks */}
          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                <i className="fa-solid fa-book-medical text-indigo-500"></i> 指南链接
              </h3>
              <div className="space-y-2">
                {analysis.guidelines.map((g, i) => (
                  <a key={i} href={g.url} target="_blank" rel="noreferrer" className="block p-3 rounded-lg bg-slate-50 hover:bg-slate-100 border border-slate-200 text-sm text-indigo-600 font-medium transition-colors">
                    {g.title} <i className="fa-solid fa-arrow-up-right-from-square text-[10px] ml-1"></i>
                  </a>
                ))}
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                <i className="fa-solid fa-list-check text-rose-500"></i> 复查/换药打卡
              </h3>
              <div className="space-y-2">
                {analysis.followUpTasks.map((task, i) => (
                  <div key={i} className="flex items-center gap-3 p-3 bg-rose-50 rounded-lg border border-rose-100 text-sm text-rose-800">
                    <input type="checkbox" className="rounded text-rose-600 focus:ring-rose-500" />
                    <span>{task}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { getResearchHelp } from '../services/geminiService';
import { ResearchInsight } from '../types';

export const ResearchAssistant: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [insight, setInsight] = useState<ResearchInsight | null>(null);

  const fetchInsight = async () => {
    if (!topic.trim()) return;
    setLoading(true);
    try {
      const data = await getResearchHelp(topic);
      setInsight(data);
    } catch (error) {
      console.error(error);
      alert("获取科研建议失败。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
        <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
          <i className="fa-solid fa-microscope text-purple-500"></i>
          科研辅助管理
        </h2>
        <div className="flex gap-2">
          <input 
            type="text"
            className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-purple-500 focus:outline-none transition-all"
            placeholder="输入你的研究领域或具体问题（如：肺癌免疫治疗耐药机制）..."
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
          />
          <button 
            onClick={fetchInsight}
            disabled={loading}
            className="bg-purple-600 hover:bg-purple-700 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-purple-200 transition-all flex items-center gap-2"
          >
            {loading ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-lightbulb"></i>}
            获取方案
          </button>
        </div>
      </div>

      {insight && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fadeIn">
          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6 h-full">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-lg">
                <i className="fa-solid fa-paperclip text-blue-500"></i> 文献推荐
              </h3>
              <div className="space-y-4">
                {insight.literatures.map((lit, i) => (
                  <div key={i} className="p-4 bg-slate-50 rounded-lg border border-slate-200 group hover:border-blue-400 transition-colors">
                    <h4 className="font-bold text-slate-800 text-sm group-hover:text-blue-600 transition-colors">{lit.title}</h4>
                    <p className="text-xs text-slate-500 mt-1">{lit.journal}</p>
                    <a href={lit.link} target="_blank" rel="noreferrer" className="text-xs text-blue-500 mt-2 inline-block hover:underline">
                      查看原文 <i className="fa-solid fa-arrow-up-right-from-square"></i>
                    </a>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-lg">
                <i className="fa-solid fa-brain text-amber-500"></i> 科研点子
              </h3>
              <div className="space-y-3">
                {insight.ideas.map((idea, i) => (
                  <div key={i} className="flex gap-3 text-sm text-slate-700">
                    <div className="w-6 h-6 rounded-full bg-amber-50 text-amber-600 flex-shrink-0 flex items-center justify-center font-bold text-xs">{i+1}</div>
                    <p className="pt-1">{idea}</p>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-lg">
                <i className="fa-solid fa-diagram-project text-emerald-500"></i> 进程管理建议
              </h3>
              <ul className="list-disc list-inside space-y-2 text-sm text-slate-600">
                {insight.managementTips.map((tip, i) => <li key={i}>{tip}</li>)}
              </ul>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

