        />
        <MobileTabButton 
          active={activeTab === AppTab.CLINICAL} 
          onClick={() => setActiveTab(AppTab.CLINICAL)}
          icon="fa-user-doctor"
          label="规培"
        />
        <MobileTabButton 
          active={activeTab === AppTab.RESEARCH} 
          onClick={() => setActiveTab(AppTab.RESEARCH)}
          icon="fa-microscope"
          label="科研"
        />
      </nav>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
      `}} />
