import React, { useState, useEffect } from 'react';
import { Habit, HabitCategory } from '../types';

export const HabitTracker: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('med-habits');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: '晨起喝水', category: HabitCategory.LIFE, completedDates: [] },
      { id: '2', name: '深蹲50个', category: HabitCategory.FITNESS, completedDates: [] },
      { id: '3', name: '阅读一篇文献', category: HabitCategory.RESEARCH, completedDates: [] },
      { id: '4', name: '记录当日开支', category: HabitCategory.FINANCE, completedDates: [] },
      { id: '5', name: '完成患者交班', category: HabitCategory.PATIENT, completedDates: [] },
    ];
  });

  const [newHabitName, setNewHabitName] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<HabitCategory>(HabitCategory.LIFE);

  // Fitness specific state
  const [workoutPlan, setWorkoutPlan] = useState('今日：胸肌+三头肌 (卧推/飞鸟/夹胸)');
  const [calories, setCalories] = useState({ intake: 0, target: 2200 });
  const [beforeImg, setBeforeImg] = useState<string | null>(null);
  const [afterImg, setAfterImg] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('med-habits', JSON.stringify(habits));
  }, [habits]);

  const addHabit = () => {
    if (!newHabitName.trim()) return;
    const newHabit: Habit = {
      id: Date.now().toString(),
      name: newHabitName,
      category: selectedCategory,
      completedDates: []
    };
    setHabits([...habits, newHabit]);
    setNewHabitName('');
  };

  const deleteHabit = (id: string) => {
    setHabits(habits.filter(h => h.id !== id));
  };

  const toggleHabit = (id: string) => {
    const today = new Date().toISOString().split('T')[0];
    setHabits(habits.map(h => {
      if (h.id === id) {
        const isDone = h.completedDates.includes(today);
        return {
          ...h,
          completedDates: isDone 
            ? h.completedDates.filter(d => d !== today) 
            : [...h.completedDates, today]
        };
      }
      return h;
    }));
  };

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, type: 'before' | 'after') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === 'before') setBeforeImg(reader.result as string);
        else setAfterImg(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="max-w-6xl mx-auto p-4 animate-fadeIn space-y-8">
      {/* Header with Visual Element */}
      <div className="relative h-48 rounded-3xl overflow-hidden shadow-2xl mb-8 group">
        <img src="https://images.unsplash.com/photo-1434494878577-86c23bcb06b9?auto=format&fit=crop&w=1200&q=80" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt="Habit banner" />
        <div className="absolute inset-0 bg-gradient-to-r from-indigo-900/80 to-transparent flex items-center px-10">
          <div>
            <h2 className="text-3xl font-black text-white mb-2 tracking-tight">自律即自由</h2>
            <p className="text-indigo-100 opacity-90">每一个习惯的养成，都是对未来的投资</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Habits Management */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6">
            <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
              <i className="fa-solid fa-plus-circle text-indigo-500"></i>
              添加习惯
            </h3>
            <div className="flex flex-wrap gap-2">
              <input 
                type="text" 
                value={newHabitName}
                onChange={(e) => setNewHabitName(e.target.value)}
                placeholder="例如：每天深蹲..."
                className="flex-1 min-w-[200px] bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none transition-all"
              />
              <select 
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value as HabitCategory)}
                className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium"
              >
                {Object.values(HabitCategory).map(cat => (
                  <option key={cat} value={cat}>{cat}</option>
                ))}
              </select>
              <button onClick={addHabit} className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-100 transition-all">
                添加
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {Object.values(HabitCategory).map(category => (
              <div key={category} className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-md transition-shadow">
                <div className="bg-slate-50/80 px-4 py-3 border-b border-slate-100 font-bold text-slate-700 flex justify-between items-center">
                  <span>{category}</span>
                  <span className="text-[10px] bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-full">
                    {habits.filter(h => h.category === category).length}
                  </span>
                </div>
                <div className="p-3 space-y-1">
                  {habits.filter(h => h.category === category).map(habit => {
                    const isDone = habit.completedDates.includes(new Date().toISOString().split('T')[0]);
                    return (
                      <div key={habit.id} className="flex items-center justify-between p-3 hover:bg-slate-50 rounded-xl group transition-all">
                        <div className="flex items-center gap-3">
                          <button 
                            onClick={() => toggleHabit(habit.id)}
                            className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all duration-300 ${isDone ? 'bg-indigo-500 border-indigo-500 scale-110 shadow-lg shadow-indigo-100' : 'border-slate-200 hover:border-indigo-300'}`}
                          >
                            {isDone && <i className="fa-solid fa-check text-white text-[10px]"></i>}
                          </button>
                          <span className={`text-sm font-medium ${isDone ? 'line-through text-slate-300' : 'text-slate-600'}`}>{habit.name}</span>
                        </div>
                        <button onClick={() => deleteHabit(habit.id)} className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-400 p-1">
                          <i className="fa-solid fa-trash-can text-xs"></i>
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Right Column: Fitness Dashboard */}
        <div className="space-y-6">
          <div className="bg-slate-900 text-white rounded-3xl shadow-xl p-6 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10">
              <i className="fa-solid fa-dumbbell text-6xl"></i>
            </div>
            <h3 className="text-xl font-black mb-4 flex items-center gap-2">
              <i className="fa-solid fa-bolt text-yellow-400"></i>
              健身专区
            </h3>

            {/* Workout Plan */}
            <div className="mb-6">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 block">今日训练计划</label>
              <textarea 
                value={workoutPlan}
                onChange={(e) => setWorkoutPlan(e.target.value)}
                className="w-full bg-slate-800/50 border border-slate-700 rounded-xl p-3 text-sm focus:outline-none focus:ring-1 focus:ring-yellow-400 h-20 resize-none"
              />
            </div>

            {/* Diet Tracking */}
            <div className="mb-6">
              <div className="flex justify-between items-end mb-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">热量摄入 (kcal)</label>
                <span className="text-xs text-yellow-400 font-bold">{calories.intake} / {calories.target}</span>
              </div>
              <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-yellow-400 transition-all duration-500" 
                  style={{ width: `${Math.min((calories.intake / calories.target) * 100, 100)}%` }}
                ></div>
              </div>
              <div className="grid grid-cols-2 gap-2 mt-3">
                <button onClick={() => setCalories({...calories, intake: calories.intake + 500})} className="bg-slate-800 hover:bg-slate-700 py-2 rounded-lg text-[10px] font-bold">+ 正餐 (500)</button>
                <button onClick={() => setCalories({...calories, intake: calories.intake + 150})} className="bg-slate-800 hover:bg-slate-700 py-2 rounded-lg text-[10px] font-bold">+ 加餐 (150)</button>
              </div>
            </div>

            {/* Comparison */}
            <div>
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 block">状态对比</label>
              <div className="grid grid-cols-2 gap-3">
                <label className="aspect-square bg-slate-800 rounded-2xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-750 transition-colors overflow-hidden relative">
                  {beforeImg ? <img src={beforeImg} className="w-full h-full object-cover" /> : (
                    <>
                      <i className="fa-solid fa-camera text-slate-600 mb-1"></i>
                      <span className="text-[10px] text-slate-500 font-bold">BEFORE</span>
                    </>
                  )}
                  <input type="file" className="hidden" onChange={(e) => handleImage(e, 'before')} />
                </label>
                <label className="aspect-square bg-slate-800 rounded-2xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-750 transition-colors overflow-hidden relative">
                   {afterImg ? <img src={afterImg} className="w-full h-full object-cover" /> : (
                    <>
                      <i className="fa-solid fa-camera text-slate-600 mb-1"></i>
                      <span className="text-[10px] text-slate-500 font-bold">AFTER</span>
                    </>
                  )}
                  <input type="file" className="hidden" onChange={(e) => handleImage(e, 'after')} />
                </label>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

