import React, { useState, useEffect } from 'react';
import { Habit, HabitCategory } from '../types';

export const HabitTracker: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('med-habits');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: '晨起喝水', category: HabitCategory.LIFE, completedDates: [] },
      { id: '2', name: '深蹲50个', category: HabitCategory.FITNESS, completedDates: [] },
      { id: '3', name: '阅读一篇文献', category: HabitCategory.RESEARCH, completedDates: [] },
      { id: '4', name: '记录当日开支', category: HabitCategory.FINANCE, completedDates: [] },
      { id: '5', name: '完成患者交班', category: HabitCategory.PATIENT, completedDates: [] },
    ];
  });

  const [newHabitName, setNewHabitName] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<HabitCategory>(HabitCategory.LIFE);
  const [workoutPlan, setWorkoutPlan] = useState('今日：胸肌+三头肌 (卧推/飞鸟/夹胸)');
  const [calories, setCalories] = useState({ intake: 0, target: 2200 });
  const [beforeImg, setBeforeImg] = useState<string | null>(null);
  const [afterImg, setAfterImg] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('med-habits', JSON.stringify(habits));
  }, [habits]);

  const addHabit = () => {
    if (!newHabitName.trim()) return;
    const newHabit: Habit = {
      id: Date.now().toString(),
      name: newHabitName,
      category: selectedCategory,
      completedDates: []
    };
    setHabits([...habits, newHabit]);
    setNewHabitName('');
  };

  const deleteHabit = (id: string) => {
    setHabits(habits.filter(h => h.id !== id));
  };

  const toggleHabit = (id: string) => {
    const today = new Date().toISOString().split('T')[0];
    setHabits(habits.map(h => {
      if (h.id === id) {
        const isDone = h.completedDates.includes(today);
        return {
          ...h,
          completedDates: isDone 
            ? h.completedDates.filter(d => d !== today) 
            : [...h.completedDates, today]
        };
      }
      return h;
    }));
  };

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, type: 'before' | 'after') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === 'before') setBeforeImg(reader.result as string);
        else setAfterImg(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const getCategoryStyles = (cat: HabitCategory) => {
    switch (cat) {
      case HabitCategory.LIFE: return "border-blue-100 bg-blue-50/30 text-blue-600 icon-fa-mug-hot";
      case HabitCategory.FITNESS: return "border-orange-100 bg-orange-50/30 text-orange-600 icon-fa-dumbbell";
      case HabitCategory.RESEARCH: return "border-purple-100 bg-purple-50/30 text-purple-600 icon-fa-microscope";
      case HabitCategory.FINANCE: return "border-emerald-100 bg-emerald-50/30 text-emerald-600 icon-fa-wallet";
      case HabitCategory.PATIENT: return "border-rose-100 bg-rose-50/30 text-rose-600 icon-fa-hospital-user";
      default: return "border-slate-100 bg-slate-50 text-slate-600 icon-fa-check";
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-4 animate-fadeIn space-y-12">
      {/* Hero Section */}
      <section className="relative h-[300px] rounded-[2.5rem] overflow-hidden shadow-2xl group">
        <img 
          src="https://images.unsplash.com/photo-1490818387583-1baba5e638af?auto=format&fit=crop&w=1600&q=80" 
          className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" 
          alt="Lifestyle" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/40 to-transparent flex flex-col justify-end p-12">
          <div className="flex items-center gap-4 mb-2">
            <span className="px-4 py-1 bg-white/20 backdrop-blur-md rounded-full text-xs font-bold text-white uppercase tracking-widest border border-white/20">Daily Rituals</span>
          </div>
          <h2 className="text-5xl font-black text-white mb-4 tracking-tighter italic">习惯，是人生的定海神针。</h2>
          <p className="text-slate-200 text-lg max-w-xl font-medium opacity-90">在这里管理你的生活、健身、科研、财商与患者工作，让自律成为一种美学。</p>
        </div>
      </section>

      {/* Habit Zones Grid */}
      <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {/* Management Card */}
        <div className="lg:col-span-1 bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 p-8 border border-slate-100 flex flex-col">
          <div className="mb-8">
            <h3 className="text-2xl font-black text-slate-800 mb-2">新建任务</h3>
            <p className="text-slate-400 text-sm">定义你的下一个微小目标</p>
          </div>
          <div className="space-y-4 flex-grow">
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">任务名称</label>
              <input 
                type="text" 
                value={newHabitName}
                onChange={(e) => setNewHabitName(e.target.value)}
                placeholder="例如：查阅心内科指南..."
                className="w-full bg-slate-50 border-2 border-slate-50 rounded-2xl px-5 py-4 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 focus:outline-none transition-all font-medium"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">所属专区</label>
              <div className="grid grid-cols-2 gap-2">
                {Object.values(HabitCategory).map(cat => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${selectedCategory === cat ? 'bg-indigo-600 border-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-50 border-transparent text-slate-500 hover:border-slate-200'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <button 
            onClick={addHabit}
            className="w-full mt-8 bg-slate-900 hover:bg-black text-white py-5 rounded-2xl font-black text-lg transition-all shadow-xl shadow-slate-200"
          >
            开启计划
          </button>
        </div>

        {/* Dynamic Habit Zones */}
        {Object.values(HabitCategory).map(category => {
          const styles = getCategoryStyles(category);
          const iconClass = styles.split(' ').find(s => s.startsWith('icon-fa-'))?.replace('icon-', '') || 'fa-check';
          const habitsInCat = habits.filter(h => h.category === category);

          return (
            <div key={category} className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 overflow-hidden border border-slate-100 flex flex-col group transition-transform hover:-translate-y-1">
              <div className={`p-8 border-b border-slate-50 flex items-center justify-between ${styles.split(' ')[1]}`}>
                <div className="flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl bg-white shadow-sm border border-slate-100 ${styles.split(' ')[2]}`}>
                    <i className={`fa-solid ${iconClass}`}></i>
                  </div>
                  <div>
                    <h4 className="text-xl font-black text-slate-800 tracking-tight">{category}专区</h4>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{habitsInCat.length} 个活跃项目</span>
                  </div>
                </div>
              </div>

              {category === HabitCategory.FITNESS && (
                <div className="px-8 pt-6 space-y-4">
                   <div className="bg-slate-950 rounded-2xl p-5 text-white">
                      <div className="flex justify-between items-center mb-4">
                        <span className="text-[10px] font-black text-orange-400 uppercase tracking-widest">Training Plan</span>
                        <i className="fa-solid fa-fire-flame-curved text-orange-500"></i>
                      </div>
                      <textarea 
                        value={workoutPlan}
                        onChange={(e) => setWorkoutPlan(e.target.value)}
                        className="w-full bg-transparent border-none text-xs font-medium text-slate-300 focus:ring-0 p-0 h-12 resize-none leading-relaxed"
                      />
                      <div className="mt-4 pt-4 border-t border-white/10 grid grid-cols-2 gap-4">
                         <div>
                            <span className="block text-[8px] text-slate-500 font-bold mb-1">CALORIES</span>
                            <span className="text-sm font-black text-white">{calories.intake} <span className="text-[10px] text-slate-500">/ {calories.target}</span></span>
                         </div>
                         <div className="flex gap-1 items-end">
                            <button onClick={() => setCalories({...calories, intake: calories.intake + 500})} className="flex-1 bg-white/10 hover:bg-white/20 h-6 rounded flex items-center justify-center text-[10px] font-bold transition-colors">Meal</button>
                            <button onClick={() => setCalories({...calories, intake: 0})} className="bg-white/10 hover:bg-white/20 h-6 w-6 rounded flex items-center justify-center text-[8px] transition-colors"><i className="fa-solid fa-rotate-left"></i></button>
                         </div>
                      </div>
                   </div>
                   <div className="grid grid-cols-2 gap-2">
                      <label className="aspect-[4/3] bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl flex items-center justify-center cursor-pointer hover:bg-slate-100 transition-all overflow-hidden relative">
                        {beforeImg ? <img src={beforeImg} className="w-full h-full object-cover" /> : <span className="text-[10px] font-black text-slate-300">BEFORE</span>}
                        <input type="file" className="hidden" onChange={(e) => handleImage(e, 'before')} />
                      </label>
                      <label className="aspect-[4/3] bg-slate-50 border-2 border-dashed border-slate-200 rounded-xl flex items-center justify-center cursor-pointer hover:bg-slate-100 transition-all overflow-hidden relative">
                        {afterImg ? <img src={afterImg} className="w-full h-full object-cover" /> : <span className="text-[10px] font-black text-slate-300">AFTER</span>}
                        <input type="file" className="hidden" onChange={(e) => handleImage(e, 'after')} />
                      </label>
                   </div>
                </div>
              )}

              <div className="p-8 space-y-3 flex-grow overflow-y-auto max-h-[300px]">
                {habitsInCat.map(habit => {
                  const isDone = habit.completedDates.includes(new Date().toISOString().split('T')[0]);
                  return (
                    <div key={habit.id} className="flex items-center justify-between p-4 bg-slate-50/50 hover:bg-slate-50 border border-transparent hover:border-slate-100 rounded-2xl group/item transition-all">
                      <div className="flex items-center gap-4">
                        <button 
                          onClick={() => toggleHabit(habit.id)}
                          className={`w-7 h-7 rounded-xl border-2 flex items-center justify-center transition-all duration-300 ${isDone ? 'bg-slate-900 border-slate-900 scale-105 shadow-lg shadow-slate-200' : 'border-slate-200 bg-white hover:border-slate-400'}`}
                        >
                          {isDone && <i className="fa-solid fa-check text-white text-[10px]"></i>}
                        </button>
                        <span className={`text-sm font-bold tracking-tight ${isDone ? 'line-through text-slate-300' : 'text-slate-600'}`}>{habit.name}</span>
                      </div>
                      <button onClick={() => deleteHabit(habit.id)} className="opacity-0 group-item-hover/item:opacity-100 text-slate-300 hover:text-red-500 transition-all p-1">
                        <i className="fa-solid fa-trash-can text-xs"></i>
                      </button>
                    </div>
                  );
                })}
                {habitsInCat.length === 0 && (
                  <div className="h-24 flex flex-col items-center justify-center text-slate-300">
                    <i className="fa-solid fa-clipboard-list text-2xl mb-2 opacity-30"></i>
                    <p className="text-[10px] font-bold uppercase tracking-widest">Empty Zone</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </section>
    </div>
  );
};

