      case HabitCategory.FINANCE: return "border-emerald-100 bg-emerald-50/30 text-emerald-600 icon-fa-coins";
      case HabitCategory.PATIENT: return "border-rose-100 bg-rose-50/30 text-rose-600 icon-fa-hospital-user";
