  { text: "穷人和中产阶级为钱而工作，富人让钱为他们工作。", author: "罗伯特·清崎", source: "《富爸爸穷爸爸》" },
  { text: "如果你没有找到一个当你睡觉时还能挣钱的方法，你将一直工作到死。", author: "巴菲特", source: "《滚雪球》" },
  { text: "买入一家伟大公司的股票，然后坐等时间发挥魔力。", author: "查理·芒格", source: "《穷查理宝典》" },
  { text: "投资的第一原则是不要亏钱，第二原则是记住第一原则。", author: "沃伦·巴菲特", source: "《价值投资》" }
];

export const HabitTracker: React.FC = () => {
  const [habits, setHabits] = useState<Habit[]>(() => {
    const saved = localStorage.getItem('med-habits');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: '晨起喝水', category: HabitCategory.LIFE, completedDates: [] },
      { id: '2', name: '深蹲50个', category: HabitCategory.FITNESS, completedDates: [] },
      { id: '3', name: '阅读一篇文献', category: HabitCategory.RESEARCH, completedDates: [] },
      { id: '4', name: '记录当日开支', category: HabitCategory.FINANCE, completedDates: [] },
      { id: '5', name: '完成患者交班', category: HabitCategory.PATIENT, completedDates: [] },
    ];
  });

  const [newHabitName, setNewHabitName] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<HabitCategory>(HabitCategory.LIFE);
  const [workoutPlan, setWorkoutPlan] = useState('今日计划：全身力量训练 45min');
  const [calories, setCalories] = useState({ intake: 0, target: 2200 });
  const [beforeImg, setBeforeImg] = useState<string | null>(null);
  const [afterImg, setAfterImg] = useState<string | null>(null);
  const [activeQuote, setActiveQuote] = useState(FINANCE_QUOTES[0]);

  useEffect(() => {
    localStorage.setItem('med-habits', JSON.stringify(habits));
    const randomQuote = FINANCE_QUOTES[Math.floor(Math.random() * FINANCE_QUOTES.length)];
    setActiveQuote(randomQuote);
  }, [habits]);

  const addHabit = () => {
    if (!newHabitName.trim()) return;
    const newHabit: Habit = {
      id: Date.now().toString(),
      name: newHabitName,
      category: selectedCategory,
      completedDates: []
    };
    setHabits([...habits, newHabit]);
    setNewHabitName('');
  };

  const deleteHabit = (id: string) => {
    setHabits(habits.filter(h => h.id !== id));
  };

  const toggleHabit = (id: string) => {
    const today = new Date().toISOString().split('T')[0];
    setHabits(habits.map(h => {
      if (h.id === id) {
        const isDone = h.completedDates.includes(today);
        return {
          ...h,
          completedDates: isDone 
            ? h.completedDates.filter(d => d !== today) 
            : [...h.completedDates, today]
        };
      }
      return h;
    }));
  };

  const handleImage = (e: React.ChangeEvent<HTMLInputElement>, type: 'before' | 'after') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === 'before') setBeforeImg(reader.result as string);
        else setAfterImg(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const getCategoryTheme = (cat: HabitCategory) => {
    switch (cat) {
      case HabitCategory.LIFE: return { bg: "bg-blue-500", icon: "fa-mug-hot", label: "生活美学" };
      case HabitCategory.FITNESS: return { bg: "bg-orange-500", icon: "fa-dumbbell", label: "硬核健身" };
      case HabitCategory.RESEARCH: return { bg: "bg-purple-500", icon: "fa-microscope", label: "科研先锋" };
      case HabitCategory.FINANCE: return { bg: "bg-emerald-600", icon: "fa-coins", label: "财富增值" };
      case HabitCategory.PATIENT: return { bg: "bg-rose-500", icon: "fa-user-md", label: "医路成长" };
      default: return { bg: "bg-slate-500", icon: "fa-check", label: "常规打卡" };
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-4 animate-fadeIn space-y-10">
      {/* Financial Wisdom Hero (Replaces Main Title) */}
      <section className="relative rounded-[2.5rem] overflow-hidden shadow-2xl bg-emerald-950 p-10 md:p-16 border-4 border-emerald-900/50 group">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none group-hover:scale-110 transition-transform duration-700">
          <i className="fa-solid fa-coins text-[200px]"></i>
        </div>
        <div className="relative z-10 flex flex-col items-center text-center space-y-6">
          <div className="px-4 py-1.5 bg-emerald-500/20 backdrop-blur-md rounded-full text-[10px] font-black text-emerald-300 uppercase tracking-[0.3em] border border-emerald-500/30">
            Professional Financial Wisdom
          </div>
          <blockquote className="max-w-3xl">
            <p className="text-2xl md:text-4xl font-black text-white leading-tight italic tracking-tight">
              “{activeQuote.text}”
            </p>
            <footer className="mt-6 flex flex-col items-center">
              <span className="text-emerald-400 font-bold text-lg">{activeQuote.author}</span>
              <span className="text-emerald-600 text-sm mt-1">{activeQuote.source}</span>
            </footer>
          </blockquote>
          <button 
            onClick={() => setActiveQuote(FINANCE_QUOTES[Math.floor(Math.random() * FINANCE_QUOTES.length)])}
            className="text-emerald-500 hover:text-white transition-colors text-xs font-bold uppercase tracking-widest mt-4 flex items-center gap-2"
          >
            <i className="fa-solid fa-rotate-right"></i> 获取更多财富洞察
          </button>
        </div>
      </section>

      {/* Global Task Add Bar */}
      <section className="bg-white rounded-[2rem] p-6 shadow-xl shadow-slate-200/50 border border-slate-100 flex flex-col md:flex-row gap-4 items-center">
        <div className="flex-1 flex gap-2 w-full">
          <input 
            type="text" 
            value={newHabitName}
            onChange={(e) => setNewHabitName(e.target.value)}
            placeholder="新建一个习惯任务..."
            className="flex-1 bg-slate-50 border-none rounded-2xl px-6 py-4 focus:ring-4 focus:ring-indigo-500/10 transition-all font-bold text-slate-700"
          />
          <select 
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value as HabitCategory)}
            className="bg-slate-100 border-none rounded-2xl px-4 py-4 text-xs font-black text-slate-500 cursor-pointer hover:bg-slate-200 transition-colors"
          >
            {Object.values(HabitCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
          </select>
        </div>
        <button 
          onClick={addHabit}
          className="w-full md:w-auto bg-slate-900 hover:bg-black text-white px-10 py-4 rounded-2xl font-black transition-all shadow-lg"
        >
          添加习惯
        </button>
      </section>

      {/* The Specialized Zones Grid */}
      <section className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-8">
        {Object.values(HabitCategory).map(category => {
          const theme = getCategoryTheme(category);
          const items = habits.filter(h => h.category === category);

          return (
            <div key={category} className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/40 border border-slate-100 flex flex-col h-full hover:shadow-2xl hover:-translate-y-1 transition-all duration-300">
              {/* Zone Header */}
              <div className={`p-8 rounded-t-[2.5rem] ${theme.bg} text-white relative overflow-hidden`}>
                <div className="absolute -right-4 -bottom-4 opacity-10 rotate-12">
                  <i className={`fa-solid ${theme.icon} text-7xl`}></i>
                </div>
                <div className="relative z-10 flex justify-between items-center">
                  <div>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">Specialized Zone</span>
                    <h4 className="text-2xl font-black">{theme.label}</h4>
                  </div>
                  <div className="bg-white/20 backdrop-blur-md px-3 py-1 rounded-full text-xs font-bold">
                    {items.length} 任务
                  </div>
                </div>
              </div>

              {/* Unique Features for Fitness Zone */}
              {category === HabitCategory.FITNESS && (
                <div className="p-8 pb-4 space-y-4">
                  <div className="bg-orange-50 rounded-2xl p-4 border border-orange-100">
                    <div className="flex justify-between items-center mb-2">
                      <span className="text-[10px] font-black text-orange-600 uppercase">Training</span>
                      <i className="fa-solid fa-bolt text-orange-400"></i>
                    </div>
                    <textarea 
                      value={workoutPlan}
                      onChange={(e) => setWorkoutPlan(e.target.value)}
                      className="w-full bg-transparent border-none text-xs font-bold text-orange-800 focus:ring-0 p-0 h-10 resize-none placeholder:text-orange-200"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <label className="aspect-[4/3] bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex items-center justify-center cursor-pointer hover:bg-slate-100 transition-all overflow-hidden relative">
                      {beforeImg ? <img src={beforeImg} className="w-full h-full object-cover" /> : <span className="text-[9px] font-black text-slate-300">BEFORE</span>}
                      <input type="file" className="hidden" onChange={(e) => handleImage(e, 'before')} />
                    </label>
                    <label className="aspect-[4/3] bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex items-center justify-center cursor-pointer hover:bg-slate-100 transition-all overflow-hidden relative">
                      {afterImg ? <img src={afterImg} className="w-full h-full object-cover" /> : <span className="text-[9px] font-black text-slate-300">AFTER</span>}
                      <input type="file" className="hidden" onChange={(e) => handleImage(e, 'after')} />
                    </label>
                  </div>
                </div>
              )}

              {/* Task List */}
              <div className="p-8 space-y-3 flex-grow overflow-y-auto max-h-[400px]">
                {items.map(habit => {
                  const isDone = habit.completedDates.includes(new Date().toISOString().split('T')[0]);
                  return (
                    <div key={habit.id} className="flex items-center justify-between p-4 bg-slate-50 hover:bg-slate-100 border border-transparent hover:border-slate-200 rounded-2xl group transition-all">
                      <div className="flex items-center gap-4">
                        <button 
                          onClick={() => toggleHabit(habit.id)}
                          className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all duration-300 ${isDone ? 'bg-slate-900 border-slate-900 scale-105 shadow-lg' : 'border-slate-300 bg-white'}`}
                        >
                          {isDone && <i className="fa-solid fa-check text-white text-xs"></i>}
                        </button>
                        <span className={`text-sm font-black tracking-tight ${isDone ? 'line-through text-slate-300' : 'text-slate-600'}`}>{habit.name}</span>
                      </div>
                      <button onClick={() => deleteHabit(habit.id)} className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-all p-2">
                        <i className="fa-solid fa-trash-can text-xs"></i>
                      </button>
                    </div>
                  );
                })}
                {items.length === 0 && (
                  <div className="h-40 flex flex-col items-center justify-center text-slate-200">
                    <i className="fa-solid fa-layer-group text-4xl mb-4 opacity-20"></i>
                    <p className="text-[10px] font-black uppercase tracking-widest">暂无活跃任务</p>
                  </div>
                )}
              </div>

              {/* Footer Stat */}
              <div className="p-6 border-t border-slate-50 flex justify-center">
                 <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
                    今日进度: {Math.round((items.filter(i => i.completedDates.includes(new Date().toISOString().split('T')[0])).length / (items.length || 1)) * 100)}%
                 </div>
              </div>
            </div>
          );
        })}
      </section>
    </div>
  );
};

