import React, { useState } from 'react';
import { AppTab } from './types';
import { HabitTracker } from './components/HabitTracker';
import { ClinicalSystem } from './components/ClinicalSystem';
import { ResearchAssistant } from './components/ResearchAssistant';

interface TabConfig {
  id: AppTab;
  label: string;
  icon: string;
  component: React.ReactNode;
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.CLINICAL);

  const [tabs, setTabs] = useState<TabConfig[]>([
    { id: AppTab.HABITS, label: '习惯养成', icon: 'fa-calendar-check', component: <HabitTracker /> },
    { id: AppTab.CLINICAL, label: '规培助手', icon: 'fa-user-doctor', component: <ClinicalSystem /> },
    { id: AppTab.RESEARCH, label: '科研辅助', icon: 'fa-microscope', component: <ResearchAssistant /> },
  ]);

  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const handleDragStart = (index: number) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;

    const newTabs = [...tabs];
    const draggedItem = newTabs[draggedIndex];
    newTabs.splice(draggedIndex, 1);
    newTabs.splice(index, 0, draggedItem);

    setDraggedIndex(index);
    setTabs(newTabs);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  // Function to download application data
  const handleDownloadData = () => {
    const data = {
      habits: JSON.parse(localStorage.getItem('med-habits') || '[]'),
      timestamp: new Date().toISOString(),
      version: "1.0.0"
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `MedQuest_Pro_Data_${new Date().toLocaleDateString()}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const ActiveComponent = tabs.find(t => t.id === activeTab)?.component;

  return (
    <div className="min-h-screen pb-20 md:pb-0 md:pt-16 bg-slate-50">
